oxy_webhelp_navlinks = {"configure_high_availability_db2-d39307e34659":{"topics":[{"title":"Db2 high availability cluster configurations","shortdesc":"<p class=\"shortdesc\">High availability cluster configurations are host-side configurations for Db2         environments on AIX and Linux operating systems. These configurations manage the failover of         applications and resources to ensure application availability during hardware or software         failures.<\/p>","href":"db2\/db2_high_avail_clstrng_config.html","attributes":{"data-id":"db2_high_avail_clstrng_config"},"menu":{"hasChildren":false},"tocID":"db2_high_avail_clstrng_config-d39307e34673","next":"db2_high_avail_clstrng_config-d39307e34673"},{"title":"High Availability Disaster Recovery","shortdesc":"<p class=\"shortdesc\">High Availability Disaster Recovery in Db2 for Linux, Unix, and Windows ensures         uninterrupted system operation and data protection against hardware failures, software         errors, natural disasters, power outages, and network issues.<\/p>","href":"db2\/high_availability_disaster_recovery.html","attributes":{"data-id":"high_availability_disaster_recovery"},"menu":{"hasChildren":false},"tocID":"high_availability_disaster_recovery-d39307e34695","next":"high_availability_disaster_recovery-d39307e34695"}]}};